function errorMessage(e){const message=e.message||String(e);const messages={'Email or password is incorrect, or account is unavailable.':'邮箱或密码不正确，或账号暂不可用。','This email is unavailable.':'该邮箱暂不可用于注册，请尝试登录或找回密码。','Enter a valid email address.':'请输入有效的邮箱地址。','Use a password with at least 12 characters.':'密码至少需要 12 位。','CERT_OPEN':'无法打开证书，请检查密码，或确认文件为受支持的 RSA P12/PFX 证书。','CERT_RSA':'请选择仅含一个 RSA 私钥的 P12/PFX 证书；本版暂不支持 ECC、SM2 或 UKey。','CERT_WEAK':'RSA 密钥至少需要 2048 位。','CERT_MATCH':'未找到与私钥唯一匹配的证书。','CERT_EXPIRED':'证书已过期或尚未生效，请更换证书。','CERT_USAGE':'此证书不允许用于数字签名。','CERT_CA':'请使用个人或企业的签署证书，而非 CA 根证书。','CERT_SIGN':'数字签名失败，未导出文件。请重新选择证书后重试。','CERT_CANCEL':'已取消证书签名。','Invalid or expired verification code. Request a new code.':'验证码错误或已过期，请重新获取。','Email delivery failed. Please try again later.':'验证码邮件发送失败，请稍后重试。','Email delivery is temporarily unavailable. Please try again later.':'邮件服务暂不可用，请稍后重试。','Too many attempts. Try again in 15 minutes.':'操作过于频繁，请 15 分钟后重试。'};const english={CERT_OPEN:'Cannot open certificate. Check its password and use an RSA P12/PFX file.',CERT_RSA:'Use a P12/PFX with one RSA private key. ECC, SM2 and hardware tokens are not supported yet.',CERT_WEAK:'RSA keys must be at least 2048 bits.',CERT_MATCH:'No unique certificate matches the private key.',CERT_EXPIRED:'The certificate has expired or is not yet valid.',CERT_USAGE:'This certificate does not permit digital signatures.',CERT_CA:'Use a signing certificate, not a CA certificate.',CERT_SIGN:'Digital signing failed. No file was exported. Select your certificate and try again.',CERT_CANCEL:'Certificate signing cancelled.'};return lang==='zh'?(messages[message]||message):(english[message]||message);}
async function api(path,options={}){const headers={'Content-Type':'application/json',...options.headers};if(csrf)headers['X-CSRF-Token']=csrf;const r=await fetch('/api'+path,{...options,headers,credentials:'same-origin'});if(!r.ok){let q;try{q=await r.json();}catch{}throw Error(typeof q?.detail==='string'?q.detail:t('Request failed. Please try again.','操作失败，请重试。'));}return r.status===204?null:r.json();}
