 const descriptions={login:t('Sign in to pick up where you left off.','登录后，即可取用你的印章与签名。'),register:t('Verify your email, then create your account.','验证邮箱后，即可创建你的签章账户。'),recover:t('Get a code by email, then set a new password.','通过邮箱接收验证码，重新设置登录密码。'),setup:t('Create the first administrator account.','设置首位管理员账号。')};
