$('auth-form').onsubmit=async e=>{e.preventDefault();$('auth-submit').disabled=true;$('auth-error').textContent='';try{let q;if(authMode==='recover'){q=await post('/recover',{email:$('auth-email').value,code:$('auth-code').value.trim(),password:$('auth-password').value});mode('login');$('auth-code').value='';$('auth-error').textContent=t('Password updated. Sign in with your new password.','密码已更新，请使用新密码登录。');}else{q=await post(authMode==='setup'?'/bootstrap':'/'+authMode,{email:$('auth-email').value,password:$('auth-password').value,name:$('auth-name').value,token:setupToken,code:$('auth-code').value.trim(),language:lang});user=q.user;csrf=q.csrf;setupToken='';await enter();}$('auth-password').value='';}catch(e){$('auth-error').textContent=errorMessage(e);}finally{$('auth-submit').disabled=false;}};
