let emailCooldown=0;
setInterval(()=>{const remaining=Math.max(0,Math.ceil((emailCooldown-Date.now())/1000));if(remaining){$('email-reset').disabled=true;$('email-reset').textContent=t(`Resend in ${remaining}s`,`${remaining} 秒后可重新发送`);}else if($('email-reset').dataset.sending!=='true'){$('email-reset').disabled=false;$('email-reset').textContent=t('Send verification code','发送验证码');}},1000);
$('email-reset').onclick=async()=>{const b=$('email-reset');if(!$('auth-email').reportValidity())return;b.disabled=true;b.dataset.sending='true';$('auth-error').textContent='';try{const registration=authMode==='register';const result=await post(registration?'/registration-email':'/recovery-email',{email:$('auth-email').value,language:lang});emailCooldown=Date.now()+(result.retryAfter||60)*1000;$('auth-error').textContent=registration?t('If this address can be registered, a 6-digit code will arrive shortly. It expires in 10 minutes. Already have an account? Sign in instead.','如果该邮箱可以注册，你将收到 6 位验证码，10 分钟内有效。已有账户请直接登录。'):t('If this email is registered, a 6-digit code will arrive shortly. It expires in 10 minutes. Check your spam folder too.','如果该邮箱已注册，你将收到 6 位验证码，10 分钟内有效。请查收邮件，也可检查垃圾邮件。');$('auth-code').focus();}catch(e){$('auth-error').textContent=errorMessage(e);}finally{b.dataset.sending='false';b.disabled=emailCooldown>Date.now();}};
async function enter(){document.body.classList.remove('auth-active');if(user.language){lang=user.language;translate();}for(const id of ['account','logout'])$(id).hidden=false;$('account').textContent=user.name;$('auth-view').hidden=true;$('workspace').hidden=user.role!=='user';$('admin-view').hidden=user.role!=='admin';if(user.role==='admin')await loadUsers();else {await loadCompanies();await refreshSavedCertificates();}}
