async function loadCompanies(prefer=localStorage.getItem('bsign-space-'+user.id)){companies=await api('/companies');$('company').replaceChildren();if(!companies.length)$('company').add(new Option(t('Create your first company','创建第一个企业'),''));companies.forEach(c=>$('company').add(new Option(c.name,c.id)));companyId=companies.some(c=>c.id===prefer)?prefer:(companies[0]?.id||'');$('company').value=companyId;await loadLibrary();}
