function openCompany(edit){companyEditing=edit;$('company-name').value=edit?(companies.find(c=>c.id===companyId)?.name||''):'';$('company-delete').hidden=!edit;$('company-dialog').querySelector('.error').textContent='';$('company-dialog').showModal();}
