$('company-delete').onclick=async()=>{if(!confirm(t('Delete this company and its saved seals? This cannot be undone.','删除此企业及其保存的印章？此操作不可撤销。')))return;try{await api('/companies/'+companyId,{method:'DELETE'});$('company-dialog').close();await loadCompanies();}catch(e){$('company-dialog').querySelector('.error').textContent=errorMessage(e);}};
function objectImage(url){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error(t('Image could not be loaded.','无法加载图片。')));im.src=url;});}
async function sealImage(record){if(imageCache.has(record.id))return imageCache.get(record.id);let url=record.url;if(!url){const r=await fetch('/api/stamps/'+record.id+'/image',{credentials:'same-origin'});if(!r.ok)throw Error(t('Seal image is unavailable.','印章图片不可用。'));url=URL.createObjectURL(await r.blob());}const original=await objectImage(url),trimmed=visibleArtwork(original);const result={originalUrl:url,url:trimmed?trimmed.toDataURL('image/png'):url,im:trimmed||original};imageCache.set(record.id,result);return result;}
async function loadLibrary(prefer){library=companyId?await api('/companies/'+companyId+'/stamps'):[];library.push(...[...tempStamps.values()].filter(x=>x.companyId===companyId));chosen=library.find(x=>x.id===prefer)||library[0]||null;renderLibrary();controls();}
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
function renderLibrary(){renderDocumentAssets();const box=$('library');box.replaceChildren();$('library-count').textContent=library.length;if(!library.length){box.append(node('p','hint',companyId?t('No seals yet. Import an image or write your name.','还没有签章，导入图片或手写姓名。'):t('Create a company to organise your seals.','先创建企业，再管理印章。')));return;}for(const r of library){const card=node('div','seal-card'+(chosen?.id===r.id?' active':''));card.draggable=true;card.ondragstart=e=>{if(!documentPdf||busy||rendering||e.target.closest('button')){e.preventDefault();return;}e.dataTransfer.setData('application/x-bsign-seal',r.id);e.dataTransfer.effectAllowed='copy';};card.tabIndex=0;card.setAttribute('role','button');const im=node('img');im.alt=r.name;im.draggable=false;sealImage(r).then(x=>im.src=x.url).catch(()=>im.alt=t('Unavailable','不可用'));const info=node('div','info');info.append(node('strong','',r.name),node('small','',`${r.width} × ${r.height} mm${r.temporary?t(' · temporary',' · 临时'):''}`));const edit=node('button','quiet edit','⋯');edit.title=t('Edit seal','编辑印章');edit.onclick=e=>{e.stopPropagation();openStamp(r);};card.append(im,info,edit);card.onclick=()=>{chosen=r;renderLibrary();controls();mobile.pick();};card.onkeydown=e=>{if(e.key==='Enter'){chosen=r;renderLibrary();controls();}};box.append(card);}}
$('import').onclick=()=>$('image-input').click();
$('image-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){notice('Use an image below 5 MB.','请选择 5 MB 以内的图片。');return;}try{const url=URL.createObjectURL(file),im=await objectImage(url);if(im.width*im.height>16000000)throw Error(t('Image is too large.','图片分辨率过大。'));await openStamp({id:'temp-'+crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),kind:'round',width:40,height:40,url,temporary:true,companyId,new:true});}catch(e){notice(errorMessage(e));}};
function stampLabels(){if(!pending)return;const editing=!pending.new;const title=$('stamp-dialog').querySelector('h2'),button=$('stamp-form').querySelector('button[type=submit]');title.dataset.en=editing?'Edit seal':'Make it yours.';title.dataset.zh=editing?'编辑签章':'设置签章';button.dataset.en=editing?'Save changes':'Use this seal';button.dataset.zh=editing?'保存修改':'使用此签章';title.textContent=title.dataset[lang];button.textContent=button.dataset[lang];}
const background=backgroundEditor($('stamp-preview'),t,result=>{pending.editedImage=result.changed?result.url:null;pending.artworkRatio=result.height/result.width;if($('stamp-kind').value==='signature')$('stamp-height').value=Math.max(3,Math.min(100,Number($('stamp-width').value)*pending.artworkRatio)).toFixed(1);});
async function openStamp(r){try{pending={...r};stampLabels();const image=await sealImage(r);$('stamp-preview').src=image.url;background.set(await objectImage(image.originalUrl),image.originalUrl);$('stamp-name').value=r.name;$('stamp-kind').value=r.kind;$('stamp-kind').disabled=!r.new;$('stamp-width').value=Number(r.width).toFixed(1);$('stamp-height').value=Number(r.height).toFixed(1);$('stamp-save').checked=!r.temporary||!!r.new;$('stamp-save').disabled=!r.temporary&&!r.new;$('stamp-dialog').querySelector('.error').textContent='';let deleteButton=$('delete-seal');if(!deleteButton){deleteButton=node('button','danger',t('Delete seal','删除签章'));deleteButton.id='delete-seal';deleteButton.type='button';$('stamp-form').querySelector('.dialog-actions').append(deleteButton);deleteButton.onclick=deleteSeal;}deleteButton.textContent=t('Delete seal','删除签章');deleteButton.hidden=!!r.new;stampDimensions();$('stamp-dialog').showModal();}catch(e){notice(errorMessage(e));}}
function stampDimensions(){const kind=$('stamp-kind').value;$('stamp-height').readOnly=kind!=='signature';if(kind!=='signature')$('stamp-height').value=$('stamp-width').value;}
$('stamp-kind').onchange=()=>{if($('stamp-kind').value==='signature'){const im=imageCache.get(pending.id)?.im;$('stamp-width').value=35;$('stamp-height').value=Math.max(3,Math.min(100,35*(pending.artworkRatio||((im?.height||1)/(im?.width||1))))).toFixed(1);}stampDimensions();};$('stamp-width').oninput=stampDimensions;
document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{$('stamp-width').value=b.dataset.size;stampDimensions();});
async function deleteSeal(){if(!confirm(t('Remove this seal from the library? Existing placements stay available until you close this workspace.','从印章库移除？当前工作区已放置的签章仍可导出。')))return;try{if(pending.temporary)tempStamps.delete(pending.id);else await api('/stamps/'+pending.id,{method:'DELETE'});$('stamp-dialog').close();await loadLibrary();}catch(e){$('stamp-dialog').querySelector('.error').textContent=errorMessage(e);}}
async function imageBase64(url){const blob=await(await fetch(url)).blob();return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob);});}
$('stamp-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const q={name:$('stamp-name').value.trim(),kind:$('stamp-kind').value,width:Number($('stamp-width').value),height:Number($('stamp-height').value)};let id=pending.id;if(pending.editedImage)q.image=await imageBase64(pending.editedImage);if($('stamp-save').checked){if(pending.temporary||pending.new){q.image=q.image||await imageBase64((await sealImage(pending)).originalUrl);const r=await post('/companies/'+companyId+'/stamps',q);id=r.id;tempStamps.delete(pending.id);}else await post('/stamps/'+id,q,'PATCH');}else tempStamps.set(id,{...pending,...q,url:pending.editedImage||pending.url,new:false,temporary:true,companyId});if(pending.editedImage)imageCache.delete(pending.id);localStorage.setItem('bsign-library-changed',JSON.stringify({user:user.id,time:Date.now()}));$('stamp-dialog').close();await loadLibrary(id);if(pending.new)notice('Seal ready. Add it to your document.','签章已就绪，可添加到文档。');else notice('Changes saved. Existing placements keep their current size.','修改已保存，页面上已放置的签章尺寸保持不变。');}catch(e){$('stamp-dialog').querySelector('.error').textContent=errorMessage(e);}finally{b.disabled=false;}};
