// Handwriting is captured and cropped locally; only an explicit library save uploads it.
const hand=$('hand-canvas'),pen=hand.getContext('2d');let writing=false,hasInk=false;
$('handwrite').onclick=()=>{pen.clearRect(0,0,hand.width,hand.height);hasInk=false;$('write-dialog').showModal();};
$('clear-hand').onclick=()=>{pen.clearRect(0,0,hand.width,hand.height);hasInk=false;};
function handPoint(e){const r=hand.getBoundingClientRect();return {x:(e.clientX-r.left)*hand.width/r.width,y:(e.clientY-r.top)*hand.height/r.height};}
hand.onpointerdown=e=>{e.preventDefault();writing=true;hasInk=true;hand.setPointerCapture(e.pointerId);const p=handPoint(e);pen.strokeStyle=$('ink').value;pen.fillStyle=pen.strokeStyle;pen.lineWidth=Number($('pen').value)*2;pen.lineCap='round';pen.lineJoin='round';pen.beginPath();pen.arc(p.x,p.y,pen.lineWidth/2,0,Math.PI*2);pen.fill();pen.beginPath();pen.moveTo(p.x,p.y);};
hand.onpointermove=e=>{if(!writing)return;const p=handPoint(e);pen.lineTo(p.x,p.y);pen.stroke();};hand.onpointerup=hand.onpointercancel=()=>writing=false;
$('use-hand').onclick=async()=>{if(!hasInk)return;const d=pen.getImageData(0,0,hand.width,hand.height).data;let left=hand.width,right=0,top=hand.height,bottom=0;for(let y=0;y<hand.height;y++)for(let x=0;x<hand.width;x++)if(d[(y*hand.width+x)*4+3]>0){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}left=Math.max(0,left-10);top=Math.max(0,top-10);right=Math.min(hand.width,right+11);bottom=Math.min(hand.height,bottom+11);const c=document.createElement('canvas');c.width=right-left;c.height=bottom-top;c.getContext('2d').drawImage(hand,left,top,c.width,c.height,0,0,c.width,c.height);const blob=await new Promise(r=>c.toBlob(r,'image/png'));$('write-dialog').close();await openStamp({id:'temp-'+crypto.randomUUID(),name:user.name,kind:'signature',width:35,height:Math.max(3,Math.min(100,35*c.height/c.width)),url:URL.createObjectURL(blob),temporary:true,companyId,new:true});};

