const viewer=$('viewer');viewer.ondragover=e=>{e.preventDefault();viewer.classList.add('dragover');};viewer.ondragleave=()=>viewer.classList.remove('dragover');viewer.ondrop=async e=>{e.preventDefault();viewer.classList.remove('dragover');const id=e.dataTransfer.getData('application/x-bsign-seal');if(id){const r=documentAssets.get(id)||library.find(r=>r.id===id),box=$('stage').getBoundingClientRect();if(!r||!documentPdf||busy||rendering||e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)return;await placeRecord(r,{x:(e.clientX-box.left)*pageSize().w/box.width,y:(e.clientY-box.top)*pageSize().h/box.height});return;}const f=e.dataTransfer.files[0];if(f&&!busy)openPdf(f);};
async function openPdf(file){
 if(busy)return;
 if((marks.length||seam)&&!confirm(t('Open another document and discard unsaved placements?','打开新文件并清除当前文件上的签章位置？')))return;
 if(file.size>100*1024*1024){notice('Use a PDF below 100 MB.','请选择 100 MB 以内的 PDF。');return;}
 setBusy(true);notice('Opening document…','正在打开文件…');
 let task=null;
 try{
  task=pdfjs.getDocument({data:await documentBytes(file,{csrf,notice,t}),cMapUrl:'/vendor/cmaps/',cMapPacked:true,standardFontDataUrl:'/vendor/standard_fonts/',wasmUrl:'/vendor/wasm/',isEvalSupported:false});
  const pdf=await task.promise;
  if(pdf.numPages>100)throw Error(t('Please split documents longer than 100 pages.','超过 100 页的文档请先拆分。'));
  // Prepare the replacement before discarding the current document or placements.
  const sizes=[];for(let i=0;i<pdf.numPages;i++){const view=(await pdf.getPage(i+1)).getViewport({scale:1});sizes.push(view.width>view.height?{w:297,h:210}:{w:210,h:297});}
  const firstPage=await baseCanvas(0,120,pdf);
  const previous=documentPdf;
  ++sequence;
  documentPdf=pdf;pageSizes=sizes;task=null;previews.clear();previews.set(0,firstPage);
  for(const id of documentAssets.keys())imageCache.delete(id);documentAssets.clear();if(chosen?.documentAsset)chosen=library[0]||null;renderLibrary();marks=[];selected=null;seam=null;$('seam').checked=false;pageIndex=0;
  wheelSum=0;wheelUntil=Date.now()+650;viewer.scrollTop=0;
  pdfName=file.name;$('filename').textContent=file.name;
  buildThumbnails();await showPage();
  // PDF.js 6 exposes document disposal on the loading task, not PDFDocumentProxy.
  if(previous)await previous.loadingTask.destroy();
  if(/\.docx?$/i.test(file.name))notice('Word converted. Review fonts, pagination and layout before signing.','Word 已转为 PDF，请先核对字体、分页和排版，再进行签章。');else notice('Ready. Pages fit A4 without cropping.','文档已就绪，页面等比例适配 A4，不裁切内容。');
 }catch(e){notice(e.name==='PasswordException'?t('Remove the PDF password before opening.','请先解除 PDF 密码保护。'):errorMessage(e));}
 finally{try{if(task)await task.destroy();}finally{setBusy(false);}}
}
function fitRect(sw,sh,w,h){const scale=Math.min(w/sw,h/sh);return {x:(w-sw*scale)/2,y:(h-sh*scale)/2,w:sw*scale,h:sh*scale};}
async function baseCanvas(index,dpi,pdf=documentPdf){const p=await pdf.getPage(index+1),v=p.getViewport({scale:1});const size=v.width>v.height?{w:297,h:210}:{w:210,h:297};const width=Math.round(size.w/25.4*dpi),height=Math.round(size.h/25.4*dpi);const fit=fitRect(v.width,v.height,width,height);const rendered=document.createElement('canvas');const viewport=p.getViewport({scale:fit.w/v.width});rendered.width=Math.ceil(viewport.width);rendered.height=Math.ceil(viewport.height);await p.render({canvasContext:rendered.getContext('2d'),viewport}).promise;const out=document.createElement('canvas');out.width=width;out.height=height;const c=out.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,width,height);c.drawImage(rendered,fit.x,fit.y,fit.w,fit.h);rendered.width=rendered.height=0;return out;}
function updatePageLabel(){$('page-label').textContent=`${pageIndex+1} / ${documentPdf.numPages}`;document.querySelectorAll('.page-thumb').forEach((el,i)=>{el.classList.toggle('active',i===pageIndex);el.setAttribute('aria-current',i===pageIndex?'page':'false');});const list=$('thumbnail-list'),active=list.children[pageIndex];if(active){const r=list.getBoundingClientRect(),a=active.getBoundingClientRect();if(getComputedStyle(list).display==='flex'){if(a.left<r.left||a.right>r.right)list.scrollLeft+=a.left-r.left-8;}else if(a.top<r.top||a.bottom>r.bottom)list.scrollTop+=a.top-r.top-8;}}
function zoom(){if(!documentPdf)return;const size=pageSize();let w;const z=$('zoom').value;if(z==='fit')w=Math.min(viewer.clientWidth-56,(viewer.clientHeight-52)*size.w/size.h);else if(z==='width')w=viewer.clientWidth-56;else w=size.w*72/25.4*Number(z);$('stage').style.width=Math.max(100,w)+'px';$('stage').style.aspectRatio=`${size.w} / ${size.h}`;}
$('zoom').onchange=zoom;window.addEventListener('resize',zoom);
async function showPage(){mobile.cancel();const seq=++sequence;rendering=true;$('work-status').textContent=t('Rendering…','正在渲染…');try{let c=previews.get(pageIndex);if(!c){const index=pageIndex;c=await baseCanvas(index,120);if(seq!==sequence)return;previews.set(index,c);while(previews.size>4){const old=previews.keys().next().value;previews.delete(old);}}if(seq!==sequence)return;const canvas=$('preview');canvas.width=c.width;canvas.height=c.height;canvas.getContext('2d').drawImage(c,0,0);$('stage').hidden=false;$('empty').hidden=true;selected=null;$('selected-info').textContent=t('Select a placed seal to adjust it.','选中页面上的签章后可调整。');updatePageLabel();zoom();drawMarks();controls();}finally{if(seq===sequence){rendering=false;$('work-status').textContent=t('Local processing','本机处理');}}}
function rotation(kind){return !['signature','date','text'].includes(kind)&&$('random').checked?Math.round((Math.random()*16-8)*10)/10:0;}
async function placeRecord(record,point=null){if(!record||!documentPdf||rendering||busy)return;const target=documentPdf,page=pageIndex;try{const {im,url}=await sealImage(record);if(documentPdf!==target||pageIndex!==page||busy||rendering)return;const m={id:crypto.randomUUID(),page,name:record.name,kind:record.kind,text:record.text,color:record.color,fontSize:record.fontSize,w:record.width,h:record.height,x:Math.max(0,Math.min(pageSize().w-record.width,(point?.x??pageSize().w/2)-record.width/2)),y:Math.max(0,Math.min(pageSize().h-record.height,(point?.y??pageSize().h/2)-record.height/2)),angle:rotation(record.kind),opacity:['round','square'].includes(record.kind)?0.85:1,im,url};marks.push(m);chosen=record;selectMark(m);}catch(e){notice(errorMessage(e));}}
$('place').onclick=()=>{if(!mobile.pick())placeRecord(chosen);};
function selectMark(m){selected=m;$('angle').value=m?.angle||0;$('selected-info').textContent=m?markLabel(m):t('Select a placed seal to adjust it.','选中页面上的签章后可调整。');drawMarks();controls();}
function drawMarks(){refreshThumbnails();const layer=$('marks-layer');layer.replaceChildren();if(!documentPdf)return;drawSeam();for(const m of marks.filter(x=>x.page===pageIndex)){const el=node('div','mark'+(selected===m?' selected':''));Object.assign(el.style,{left:m.x/pageSize().w*100+'%',top:m.y/pageSize().h*100+'%',width:m.w/pageSize().w*100+'%',height:m.h/pageSize().h*100+'%',transform:`rotate(${m.angle}deg)`});const im=node('img');im.src=m.url;im.alt=m.name;im.draggable=false;im.style.objectFit='contain';im.style.opacity=String(m.opacity??1);el.append(im);const remove=node('button','mark-delete','×');remove.type='button';remove.title=t('Remove from this page','从当前页移除');remove.setAttribute('aria-label',t('Remove mark','移除签章'));remove.onpointerdown=e=>e.stopPropagation();remove.ondblclick=e=>e.stopPropagation();remove.onclick=e=>{e.preventDefault();e.stopPropagation();if(busy||rendering)return;marks=marks.filter(item=>item!==m);selectMark(null);};el.append(remove);if(['signature','date','text'].includes(m.kind)){const handle=node('button','resize-handle');handle.type='button';handle.setAttribute('aria-label',t('Resize signature','调整签名大小'));el.append(handle);handle.onpointerdown=e=>{if(busy||rendering)return;e.preventDefault();e.stopPropagation();selected=m;controls();handle.setPointerCapture(e.pointerId);const start={x:e.clientX,y:e.clientY,w:m.w,h:m.h,cx:m.x+m.w/2,cy:m.y+m.h/2};handle.onpointermove=ev=>{const r=$('stage').getBoundingClientRect(),dx=(ev.clientX-start.x)*pageSize().w/r.width,dy=(ev.clientY-start.y)*pageSize().h/r.height,a=m.angle*Math.PI/180,lx=dx*Math.cos(a)+dy*Math.sin(a),ly=-dx*Math.sin(a)+dy*Math.cos(a);resizeSignature(start.w*(1+2*(lx*start.w+ly*start.h)/(start.w**2+start.h**2)),false,{x:start.cx,y:start.cy});Object.assign(el.style,{left:m.x/pageSize().w*100+'%',top:m.y/pageSize().h*100+'%',width:m.w/pageSize().w*100+'%',height:m.h/pageSize().h*100+'%'});};handle.onpointerup=handle.onpointercancel=()=>{handle.onpointermove=null;refreshThumbnails();};};}if(m.kind==='text')el.ondblclick=()=>openText(m);layer.append(el);el.onpointerdown=e=>{if(busy||rendering)return;e.preventDefault();selected=m;$('selected-info').textContent=markLabel(m);$('angle').value=m.angle;layer.querySelectorAll('.mark').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');controls();el.setPointerCapture(e.pointerId);const start={x:e.clientX,y:e.clientY,mx:m.x,my:m.y};el.onpointermove=ev=>{const r=$('stage').getBoundingClientRect();m.x=Math.max(0,Math.min(pageSize().w-m.w,start.mx+(ev.clientX-start.x)*pageSize().w/r.width));m.y=Math.max(0,Math.min(pageSize().h-m.h,start.my+(ev.clientY-start.y)*pageSize().h/r.height));el.style.left=m.x/pageSize().w*100+'%';el.style.top=m.y/pageSize().h*100+'%';};el.onpointerup=el.onpointercancel=()=>{el.onpointermove=null;refreshThumbnails();};};}}
$('angle').oninput=()=>{if(selected){selected.angle=Number($('angle').value);drawMarks();}};
$('remove-mark').onclick=()=>{marks=marks.filter(m=>m!==selected);selectMark(null);};
$('copy-all').onclick=()=>{if(!selected)return;for(let p=0;p<documentPdf.numPages;p++)if(p!==pageIndex){const from=pageSize(),to=pageSize(p);marks.push({...selected,id:crypto.randomUUID(),page:p,x:Math.max(0,Math.min(to.w-selected.w,selected.x/from.w*to.w)),y:Math.max(0,Math.min(to.h-selected.h,selected.y/from.h*to.h)),angle:rotation(selected.kind)});}refreshThumbnails();notice('Copied to other pages. Review before export.','已复制到其他页面，请在导出前核对。');};
function rotatedSeal(im,angle){const base=Math.max(im.width,im.height),radians=angle*Math.PI/180,size=Math.ceil(base*(Math.abs(Math.cos(radians))+Math.abs(Math.sin(radians)))),c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');ctx.translate(size/2,size/2);ctx.rotate(angle*Math.PI/180);const f=fitRect(im.width,im.height,base,base);ctx.drawImage(im,f.x-base/2,f.y-base/2,f.w,f.h);return c;}
$('seam').onchange=async()=>{if(!$('seam').checked){seam=null;drawSeam();controls();return;}if(!chosen||['signature','date','text'].includes(chosen.kind))return;try{const {im}=await sealImage(chosen);const rotated=rotatedSeal(im,rotation(chosen.kind)),ratio=rotated.width/Math.max(im.width,im.height);seam={canvas:rotated,opacity:0.85,w:chosen.width*ratio,h:chosen.height*ratio,y:Number($('seam-y').value),name:chosen.name};drawSeam();controls();notice('Across-page seal added using the selected seal and size.','骑缝章已按所选印章及尺寸添加。');}catch(e){$('seam').checked=false;notice(errorMessage(e));}};
$('seam-y').oninput=()=>{if(seam){seam.y=Number($('seam-y').value);drawSeam();}};
function drawSeam(){syncSeamPosition();refreshThumbnails();const layer=$('seam-layer');layer.replaceChildren();if(!seam||!documentPdf)return;const n=documentPdf.numPages,c=node('canvas','seam-slice');const sw=seam.canvas.width/n;c.width=Math.max(1,Math.ceil(sw));c.height=seam.canvas.height;c.getContext('2d').drawImage(seam.canvas,pageIndex*sw,0,sw,seam.canvas.height,0,0,c.width,c.height);Object.assign(c.style,{right:0,top:seam.y/100*(pageSize().h-seam.h)/pageSize().h*100+'%',width:seam.w/n/pageSize().w*100+'%',height:seam.h/pageSize().h*100+'%'});c.style.opacity=String(seam.opacity??1);c.style.pointerEvents='auto';c.style.cursor='ns-resize';c.style.touchAction='none';c.onpointerdown=e=>{if(busy||rendering)return;e.preventDefault();e.stopPropagation();c.setPointerCapture(e.pointerId);const startY=e.clientY,startTop=seam.y/100*(pageSize().h-seam.h);c.onpointermove=ev=>{const mm=startTop+(ev.clientY-startY)*pageSize().h/$('stage').getBoundingClientRect().height;const max=pageSize().h-seam.h;seam.y=Math.max(0,Math.min(100,mm/max*100));c.style.top=seam.y/100*max/pageSize().h*100+'%';syncSeamPosition();};c.onpointerup=c.onpointercancel=()=>{c.onpointermove=null;refreshThumbnails();};};layer.append(c);}
let wheelUntil=0,wheelSum=0,wheelTime=0,wheelDir=0;
async function turn(dir){if(!documentPdf||busy||rendering||pageIndex+dir<0||pageIndex+dir>=documentPdf.numPages)return;const old=pageIndex;pageIndex+=dir;try{await showPage();viewer.scrollTop=dir>0?0:viewer.scrollHeight;}catch(e){pageIndex=old;notice(errorMessage(e));}finally{wheelUntil=Date.now()+650;wheelSum=0;}}
$('prev').onclick=()=>turn(-1);$('next').onclick=()=>turn(1);
viewer.addEventListener('wheel',e=>{if(!documentPdf||e.ctrlKey||Math.abs(e.deltaX)>Math.abs(e.deltaY))return;const d=Math.sign(e.deltaY),now=Date.now(),edge=d>0?viewer.scrollTop+viewer.clientHeight>=viewer.scrollHeight-3:viewer.scrollTop<=3;if(!edge){wheelSum=0;return;}if(pageIndex+d<0||pageIndex+d>=documentPdf.numPages)return;e.preventDefault();if(busy||rendering||now<wheelUntil)return;if(now-wheelTime>250||d!==wheelDir)wheelSum=0;wheelTime=now;wheelDir=d;wheelSum+=Math.abs(e.deltaY)*(e.deltaMode===1?16:e.deltaMode===2?viewer.clientHeight:1);if(wheelSum>=70)turn(d);},{passive:false});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='Delete'&&selected&&!busy){marks=marks.filter(m=>m!==selected);selectMark(null);}if(e.key==='PageDown')turn(1);if(e.key==='PageUp')turn(-1);});
function paintMark(ctx,m,scale){ctx.save();ctx.globalAlpha=m.opacity??1;ctx.translate((m.x+m.w/2)*scale,(m.y+m.h/2)*scale);ctx.rotate(m.angle*Math.PI/180);const r=fitRect(m.im.width,m.im.height,m.w*scale,m.h*scale);ctx.drawImage(m.im,-m.w*scale/2+r.x,-m.h*scale/2+r.y,r.w,r.h);ctx.restore();}
async function exportPdf(certificate=null){if(!documentPdf||busy||rendering){certificate?.close();return;}setBusy(true);try{const out=await PDFLib.PDFDocument.create();for(let p=0;p<documentPdf.numPages;p++){notice(`Building page ${p+1} of ${documentPdf.numPages} on your device…`,`正在本机合成第 ${p+1} / ${documentPdf.numPages} 页…`);const c=await baseCanvas(p,300),ctx=c.getContext('2d'),size=pageSize(p),scale=c.width/size.w;if(seam){const sw=seam.canvas.width/documentPdf.numPages,dw=seam.w/documentPdf.numPages*scale;ctx.save();ctx.globalAlpha=seam.opacity??1;ctx.drawImage(seam.canvas,p*sw,0,sw,seam.canvas.height,c.width-dw,seam.y/100*(size.h-seam.h)*scale,dw,seam.h*scale);ctx.restore();}for(const m of marks.filter(x=>x.page===p))paintMark(ctx,m,scale);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));const image=await out.embedPng(await blob.arrayBuffer());out.addPage([size.w*72/25.4,size.h*72/25.4]).drawImage(image,{x:0,y:0,width:size.w*72/25.4,height:size.h*72/25.4});c.width=c.height=0;await new Promise(r=>setTimeout(r,0));}let bytes=await out.save();if(certificate){notice('Signing with your certificate locally…','正在本机使用你的证书签名…');bytes=await certificate.sign(bytes);}const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const a=node('a');a.href=url;a.download=pdfName.replace(/\.(pdf|docx?|jpe?g|png)$/i,'')+'-BSign.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);if(certificate)notice('Digitally signed PDF exported. Open it in a PDF reader to verify the certificate.','数字签名 PDF 已导出，可在 PDF 阅读器中验证证书。');else notice('Done. Your flattened PDF is ready in Downloads.','已完成，图片型 PDF 已交给浏览器下载。');}catch(e){notice(errorMessage(e));}finally{certificate?.close();setBusy(false);}}
$('export').onclick=()=>{if(!documentPdf||busy||rendering)return;if($('certificate-enabled').checked)openCertificate();else exportPdf();};
