let allUsers=[];async function loadUsers(){allUsers=await api('/admin/users');renderUsers();}
function renderUsers(){const box=$('user-list');box.replaceChildren();const query=$('user-search').value.toLowerCase();for(const u of allUsers.filter(x=>(x.email+' '+x.name).toLowerCase().includes(query))){const row=node('div','user-row'),info=node('div','user-info');info.append(node('strong','',u.name),node('small','',u.email));row.append(info,node('span','hint',u.role==='admin'?t('Administrator','管理员'):u.active?t('Active','正常'):t('Suspended','已停用')));if(u.role!=='admin'){const b=node('button',u.active?'danger':'secondary',u.active?t('Suspend','停用'):t('Enable','启用'));b.onclick=async()=>{if(!confirm(t('Update access for ','更新访问权限：')+u.email+'?'))return;try{await post('/admin/users/'+u.id,{active:!u.active},'PATCH');await loadUsers();}catch(e){alert(errorMessage(e));}};row.append(b);}box.append(row);}}
