let phoneSession=null,phoneTimer=null,phoneGeneration=0;
async function stopPhone(){const old=phoneSession;phoneSession=null;++phoneGeneration;clearTimeout(phoneTimer);if(old)try{await api('/phone-sign/'+old.id,{method:'DELETE'});}catch{}}
async function beginPhone(){
 const button=$('phone-sign');button.disabled=true;$('phone-renew').disabled=true;
 await stopPhone();const generation=phoneGeneration;
 try{
  const q=await post('/phone-sign',{language:lang});
  if(generation!==phoneGeneration){await api('/phone-sign/'+q.id,{method:'DELETE'});return;}
  phoneSession={...q,companyId};$('phone-qr').src=q.qr;$('phone-status').textContent=t('Waiting for your signature…','等待手机签名…');
  $('write-dialog').close();if(!$('phone-dialog').open)$('phone-dialog').showModal();
  phoneTimer=setTimeout(()=>pollPhone(generation),1500);
 }catch(e){notice(errorMessage(e));$('phone-status').textContent=errorMessage(e);}finally{button.disabled=false;$('phone-renew').disabled=false;}
}
async function pollPhone(generation){
 if(generation!==phoneGeneration||!phoneSession)return;
 const session=phoneSession;
 if(Date.now()>=session.expires*1000){$('phone-status').textContent=t('QR code expired. Generate a new one.','二维码已过期，请重新生成。');await stopPhone();return;}
 try{
  const q=await api('/phone-sign/'+session.id);
  if(generation!==phoneGeneration)return;
  if(q.ready){
   const url='data:image/png;base64,'+q.image,im=await objectImage(url);
   if(generation!==phoneGeneration)return;
   if(companyId!==session.companyId)throw Error(t('Company changed. Please start again.','企业已切换，请重新发起签名。'));
   $('phone-dialog').close();await stopPhone();
   await openStamp({id:'temp-'+crypto.randomUUID(),name:user.name,kind:'signature',width:35,height:Math.max(3,Math.min(100,35*im.height/im.width)),url,temporary:true,companyId,new:true});
   $('stamp-save').checked=false;
   notice('Signature received. Review it before adding it to your PDF.','已收到手机签名，请核对后添加到 PDF。');return;
  }
  $('phone-status').textContent=t('Waiting for your signature…','等待手机签名…');
 }catch(e){if(generation!==phoneGeneration)return;$('phone-status').textContent=t('Connection interrupted. Retrying…','连接暂时中断，正在重试…');}
 if(generation===phoneGeneration)phoneTimer=setTimeout(()=>pollPhone(generation),2000);
}
$('phone-sign').onclick=beginPhone;$('phone-renew').onclick=beginPhone;$('phone-dialog').addEventListener('close',()=>stopPhone());

function markLabel(m){if(['date','text'].includes(m.kind))return `${m.name} · ${Number(m.fontSize.toFixed(1))} pt`;return `${m.name} · ${Number(m.w.toFixed(1))} × ${Number(m.h.toFixed(1))} mm`;}
function sizeControls(){$('date-size-field').hidden=!['date','text'].includes(selected?.kind);$('placed-date-font').disabled=!['date','text'].includes(selected?.kind)||busy;if(['date','text'].includes(selected?.kind))$('placed-date-font').value=Number(selected.fontSize.toFixed(1));const enabled=['signature','date','text'].includes(selected?.kind);$('size-field').hidden=!enabled;for(const id of ['size-down','size-up','mark-width'])$(id).disabled=!enabled||busy;if(enabled)$('mark-width').value=Number(selected.w.toFixed(1));}
function resizeSignature(width,redraw=true,center=null){if(!selected||!['signature','date','text'].includes(selected.kind)||busy||rendering||!Number.isFinite(width))return;const m=selected,ratio=m.h/m.w,a=m.angle*Math.PI/180,c=Math.abs(Math.cos(a)),s=Math.abs(Math.sin(a)),max=Math.min(['date','text'].includes(m.kind)?pageSize().w:150,pageSize().w/(c+ratio*s),pageSize().h/(s+ratio*c));const cx=center?.x??m.x+m.w/2,cy=center?.y??m.y+m.h/2;const previousWidth=m.w;m.w=Math.max(Math.min(5,max),Math.min(max,width));if(['date','text'].includes(m.kind))m.fontSize*=m.w/previousWidth;m.h=m.w*ratio;const halfX=(m.w*c+m.h*s)/2,halfY=(m.w*s+m.h*c)/2;m.x=Math.max(halfX,Math.min(pageSize().w-halfX,cx))-m.w/2;m.y=Math.max(halfY,Math.min(pageSize().h-halfY,cy))-m.h/2;$('selected-info').textContent=markLabel(m);sizeControls();if(redraw)drawMarks();}
$('mark-width').onchange=()=>{const value=$('mark-width').valueAsNumber;if(Number.isFinite(value))resizeSignature(value);else sizeControls();};$('size-down').onclick=()=>resizeSignature(selected.w/1.1);$('size-up').onclick=()=>resizeSignature(selected.w*1.1);
const dateFormats={spaced:(y,m,d)=>`${y}　${m}　${d}`,cn:(y,m,d)=>`${y}年${Number(m)}月${Number(d)}日`,iso:(y,m,d)=>`${y}-${m}-${d}`,slash:(y,m,d)=>`${y}/${m}/${d}`,dot:(y,m,d)=>`${y}.${m}.${d}`,dmy:(y,m,d)=>`${d}/${m}/${y}`,en:(y,m,d)=>`${Number(d)} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(m)-1]} ${y}`,long:(y,m,d)=>`${['January','February','March','April','May','June','July','August','September','October','November','December'][Number(m)-1]} ${Number(d)}, ${y}`};
function dateText(){const parts=$('date-value').value.split('-');return parts.length===3?dateFormats[$('date-format').value](...parts):'';}
function previewDate(){$('date-gap-field').hidden=$('date-format').value!=='spaced';const preview=$('date-preview');preview.style.fontFamily='"Microsoft YaHei", "PingFang SC", Arial, sans-serif';preview.style.fontSize=(Number($('date-font').value)||12)+'pt';preview.replaceChildren();if($('date-format').value==='spaced'){preview.style.display='flex';preview.style.gap=(Number($('date-gap').value)||0)+'mm';for(const text of $('date-value').value.split('-'))preview.append(node('span','',text));}else{preview.style.display='block';preview.textContent=dateText();}$('date-preview').style.color=$('date-color').value;const parts=$('date-value').value.split('-');if(parts.length===3)for(const option of $('date-format').options)option.textContent=dateFormats[option.value](...parts);}
$('date-stamp').onclick=()=>{if(!documentPdf||busy||rendering)return;const d=new Date();$('date-value').value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;previewDate();$('date-dialog').showModal();};for(const id of ['date-value','date-format','date-color','date-font','date-gap'])$(id).oninput=previewDate;
$('placed-date-font').onchange=()=>{const value=$('placed-date-font').valueAsNumber;if(['date','text'].includes(selected?.kind)&&Number.isFinite(value)&&value>=6&&value<=36)resizeSignature(selected.w*value/selected.fontSize);else sizeControls();};
$('date-form').onsubmit=e=>{e.preventDefault();const text=dateText(),fontSize=$('date-font').valueAsNumber,gap=$('date-gap').valueAsNumber;if(!text||!documentPdf||busy||rendering||fontSize<6||fontSize>36||!Number.isFinite(fontSize)||!Number.isFinite(gap))return;const c=document.createElement('canvas'),ctx=c.getContext('2d'),font='64px "Microsoft YaHei", "PingFang SC", Arial, sans-serif',mmPerPixel=fontSize/64*25.4/72;ctx.font=font;const parts=$('date-format').value==='spaced'?$('date-value').value.split('-'):[text],gapPixels=gap/mmPerPixel;const widths=parts.map(part=>ctx.measureText(part).width);c.width=Math.ceil(widths.reduce((a,b)=>a+b,0)+(parts.length-1)*gapPixels)+24;c.height=110;ctx.font=font;ctx.fillStyle=$('date-color').value;ctx.textBaseline='middle';let x=12;parts.forEach((part,i)=>{ctx.fillText(part,x,55);x+=widths[i]+gapPixels;});const trimmed=visibleArtwork(c)||c,w=trimmed.width*mmPerPixel,h=trimmed.height*mmPerPixel;if(w>pageSize().w||h>pageSize().h){notice('Reduce the font size or spacing to fit A4.','字号或间距过大，请调小后再添加。');return;}$('date-dialog').close();const m={id:crypto.randomUUID(),name:text,kind:'date',fontSize,page:pageIndex,w,h,x:(pageSize().w-w)/2,y:(pageSize().h-h)/2,angle:0,im:trimmed,url:trimmed.toDataURL('image/png')};addDocumentAsset(m);notice('Date ready in temporary items. Drag it onto the PDF.','日期已放到右侧临时素材区，请拖到 PDF 的指定位置。');};

let certSession=null,certInfo=null;
function clearCertificate(){certSession?.close();certSession=null;certInfo=null;$('certificate-password').value='';$('certificate-details').replaceChildren();$('certificate-submit').textContent=t('Review certificate','读取证书');}
async function openCertificate(){clearCertificate();$('certificate-source').replaceChildren(new Option(t('Select a saved certificate','请选择已保存的证书'),''));$('certificate-source').value='';certificateSourceChanged();$('certificate-error').textContent='';$('certificate-dialog').showModal();try{const rows=await api('/certificates');for(const row of rows)if(row.expires*1000>Date.now())$('certificate-source').append(new Option(row.name+' · '+(row.source==='bsign-ca'?'BSign Community':row.source==='imported'?t('Imported','自行导入'):t('Self-signed','旧版自签名')),row.id));const chosen=$('saved-certificate').value;if(chosen){if(rows.some(row=>row.id===chosen&&row.expires*1000>Date.now())){$('certificate-source').value=chosen;certificateSourceChanged();$('certificate-password').focus();}else throw Error(t('Selected certificate is unavailable. Refresh the list.','所选证书已不可用，请刷新列表。'));}}catch(e){$('certificate-error').textContent=errorMessage(e);}}
function certificateSourceChanged(){clearCertificate();$('certificate-submit').disabled=!$('certificate-source').value;$('stored-certificate-note').hidden=!$('certificate-source').value;}
$('certificate-source').onchange=certificateSourceChanged;
$('certificate-dialog').addEventListener('close',clearCertificate);
$('certificate-password').oninput=()=>{certSession?.close();certSession=null;certInfo=null;$('certificate-details').replaceChildren();$('certificate-submit').textContent=t('Review certificate','读取证书');};
$('certificate-form').onsubmit=async e=>{e.preventDefault();const button=$('certificate-submit');button.disabled=true;$('certificate-error').textContent='';try{if(certInfo&&certSession){const session=certSession;certSession=null;certInfo=null;$('certificate-dialog').close();await exportPdf(session);return;}let file;const saved=$('certificate-source').value;if(!saved)throw Error(t('Add a certificate in certificate management first.','请先在证书管理中添加证书。'));if(saved){const response=await fetch('/api/certificates/'+encodeURIComponent(saved)+'/download',{credentials:'same-origin'});if(!response.ok)throw Error(t('Certificate unavailable. Refresh the certificate list.','证书不可用，请重新打开证书列表。'));file=await response.blob();}if(!file||file.size>2*1024*1024)throw Error(t('Select a P12/PFX file smaller than 2 MB.','请选择小于 2 MB 的 P12/PFX 证书文件。'));const session=certificateSession();certSession=session;const password=$('certificate-password').value;$('certificate-password').value='';const info=await session.inspect(await file.arrayBuffer(),password);if(certSession!==session)return;certInfo=info;const box=$('certificate-details');for(const [label,value] of [[t('Holder','持有人'),info.subject],[t('Issuer','签发者'),info.issuer],[t('Valid from','有效期起'),new Date(info.from).toLocaleDateString()],[t('Valid until','有效期止'),new Date(info.until).toLocaleDateString()],[t('SHA-256 fingerprint','SHA-256 指纹'),info.fingerprint]]){box.append(node('strong','',label),node('p','',value));}button.textContent=t('Sign and export PDF','确认签名并导出 PDF');}catch(e){if(e.message==='CERT_CANCEL')return;$('certificate-error').textContent=errorMessage(e);certSession?.close();certSession=null;certInfo=null;}finally{button.disabled=false;}};

let thumbnailGeneration=0,thumbnailObserver=null,thumbnailQueue=Promise.resolve();
const thumbnailBases=new Map();
function drawThumbnail(index){const base=thumbnailBases.get(index),canvas=$('thumb-'+index);if(!base||!canvas)return;canvas.width=base.width;canvas.height=base.height;const ctx=canvas.getContext('2d');ctx.drawImage(base,0,0);const size=pageSize(index),scale=canvas.width/size.w;if(seam){const sw=seam.canvas.width/documentPdf.numPages,dw=seam.w/documentPdf.numPages*scale;ctx.save();ctx.globalAlpha=seam.opacity??1;ctx.drawImage(seam.canvas,index*sw,0,sw,seam.canvas.height,canvas.width-dw,seam.y/100*(size.h-seam.h)*scale,dw,seam.h*scale);ctx.restore();}for(const m of marks.filter(m=>m.page===index))paintMark(ctx,m,scale);}
function refreshThumbnails(){for(const index of thumbnailBases.keys())drawThumbnail(index);}
function buildThumbnails(){const generation=++thumbnailGeneration,pdf=documentPdf;thumbnailObserver?.disconnect();thumbnailBases.clear();thumbnailQueue=Promise.resolve();$('thumbnail-list').replaceChildren();$('thumbnail-count').textContent=pdf.numPages;
 thumbnailObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){thumbnailObserver.unobserve(entry.target);const index=Number(entry.target.dataset.page);thumbnailQueue=thumbnailQueue.then(async()=>{if(generation!==thumbnailGeneration)return;try{const base=await baseCanvas(index,36,pdf);if(generation!==thumbnailGeneration)return;thumbnailBases.set(index,base);drawThumbnail(index);}catch{}});}}, {root:$('thumbnail-list'),rootMargin:'200px'});
 for(let i=0;i<pdf.numPages;i++){const button=node('button','page-thumb');button.type='button';button.dataset.page=i;button.setAttribute('aria-label',String(i+1));const canvas=node('canvas');canvas.id='thumb-'+i;canvas.width=pageSize(i).w;canvas.height=pageSize(i).h;button.append(canvas,node('span','',String(i+1)));button.onclick=async()=>{if(!documentPdf||busy||rendering||i===pageIndex)return;const old=pageIndex;pageIndex=i;try{await showPage();viewer.scrollTop=0;}catch(e){pageIndex=old;notice(errorMessage(e));}};$('thumbnail-list').append(button);thumbnailObserver.observe(button);}
}

async function refreshSavedCertificates(){const select=$('saved-certificate');$('refresh-certificates').disabled=true;try{const items=await api('/certificates'),previous=select.value;select.replaceChildren(new Option(t('Select a saved certificate','请选择已保存的证书'),''));for(const item of items)if(item.expires*1000>Date.now())select.append(new Option(item.name,item.id));select.value=[...select.options].some(x=>x.value===previous)?previous:'';$('saved-certificate-status').textContent=items.length?t('Select a saved certificate. BSign certificates do not verify identity.','请选择已保存的证书。BSign 签发证书不验证身份。'):t('No saved certificates yet. Generate one in certificate management.','还没有已保存证书，可前往证书管理生成。');}catch(e){$('saved-certificate-status').textContent=errorMessage(e);}finally{$('refresh-certificates').disabled=false;}}
$('certificate-enabled').onchange=()=>{$('export-certificate').hidden=!$('certificate-enabled').checked;if($('certificate-enabled').checked)refreshSavedCertificates();};
$('refresh-certificates').onclick=refreshSavedCertificates;
window.addEventListener('focus',()=>{if(user?.role==='user'&&$('certificate-enabled').checked&&!$('certificate-dialog').open)refreshSavedCertificates();});
let editingText=null;
function previewText(){$('text-preview').textContent=$('text-value').value;$('text-preview').style.fontSize=($('text-font').valueAsNumber||12)+'pt';$('text-preview').style.color=$('text-color').value;}
function openText(m=null){if(!documentPdf||busy||rendering)return;editingText=m;$('text-value').value=m?.text||'';$('text-font').value=m?.fontSize||12;$('text-color').value=m?.color||'#18343a';$('text-error').textContent='';previewText();$('text-dialog').showModal();$('text-value').focus();}
$('text-stamp').onclick=()=>openText();for(const id of ['text-value','text-font','text-color'])$(id).oninput=previewText;
$('text-form').onsubmit=e=>{e.preventDefault();const text=$('text-value').value.trim(),fontSize=$('text-font').valueAsNumber,color=$('text-color').value;if(!text||!documentPdf||busy||rendering||!Number.isFinite(fontSize)||fontSize<6||fontSize>36)return;const lines=text.split(/\r?\n/);if(lines.length>30){$('text-error').textContent=t('Use up to 30 lines.','最多支持 30 行文字。');return;}const c=document.createElement('canvas'),ctx=c.getContext('2d'),font='64px "Microsoft YaHei", "PingFang SC", Arial, sans-serif',mmPerPixel=fontSize/64*25.4/72;ctx.font=font;const width=Math.ceil(Math.max(...lines.map(line=>ctx.measureText(line).width)))+24,height=lines.length*92+24;if(width*mmPerPixel>pageSize().w||height*mmPerPixel>pageSize().h||width*height>16000000){$('text-error').textContent=t('Text is too large for this page. Add line breaks or reduce the font size.','文字超出页面，请换行或调小字号。');return;}c.width=width;c.height=height;ctx.font=font;ctx.fillStyle=color;ctx.textBaseline='middle';lines.forEach((line,i)=>ctx.fillText(line,12,58+i*92));const trimmed=visibleArtwork(c);if(!trimmed)return;const w=trimmed.width*mmPerPixel,h=trimmed.height*mmPerPixel;const m=editingText||{id:crypto.randomUUID(),page:pageIndex,angle:0};Object.assign(m,{name:text.replace(/\s+/g,' ').slice(0,35),text,color,kind:'text',fontSize,w,h,x:Math.max(0,Math.min(pageSize().w-w,m.x??(pageSize().w-w)/2)),y:Math.max(0,Math.min(pageSize().h-h,m.y??(pageSize().h-h)/2)),im:trimmed,url:trimmed.toDataURL('image/png')});const placed=editingText&&!editingText.documentAsset;$('text-dialog').close();editingText=null;if(placed)selectMark(m);else addDocumentAsset(m);notice('Text ready. Select the temporary item to place it on your document.','文字已就绪。选择临时素材，再放置到文档的目标位置。');};

function syncSeamPosition(){const max=seam?Math.max(0,pageSize().h-seam.h):0;$('seam-top').max=max.toFixed(1);$('seam-top').value=seam?(seam.y/100*max).toFixed(1):'';if(seam)$('seam-y').value=seam.y;}
function setSeamTop(mm){if(!seam||busy||rendering||!Number.isFinite(mm))return;const max=Math.max(0,pageSize().h-seam.h);seam.y=max?Math.max(0,Math.min(max,mm))/max*100:0;drawSeam();}
$('seam-top').onchange=()=>{setSeamTop($('seam-top').valueAsNumber);syncSeamPosition();};$('seam-up').onclick=()=>setSeamTop($('seam-top').valueAsNumber-1);$('seam-down').onclick=()=>setSeamTop($('seam-top').valueAsNumber+1);

function addDocumentAsset(m){const record={...m,width:m.w,height:m.h,documentAsset:true};documentAssets.set(record.id,record);imageCache.delete(record.id);chosen=record;selected=null;$('selected-info').textContent=t('Drag a temporary item onto the PDF.','将临时素材拖到 PDF 上。');renderLibrary();drawMarks();controls();}
function renderDocumentAssets(){let box=$('document-assets');if(!box){box=node('section','document-assets');box.id='document-assets';$('library').after(box);}box.hidden=!documentAssets.size;box.replaceChildren();if(!documentAssets.size)return;box.append(node('h3','',t('Temporary items','临时素材')),node('p','hint',t('Drag onto the PDF. Only for this document.','拖到 PDF 的指定位置，仅用于当前文件。')));for(const r of documentAssets.values()){const card=node('div','seal-card'+(chosen?.id===r.id?' active':''));card.dataset.assetId=r.id;card.draggable=true;card.tabIndex=0;card.setAttribute('role','button');card.ondragstart=e=>{if(busy||rendering||!documentPdf||e.target.closest('button')){e.preventDefault();return;}e.dataTransfer.setData('application/x-bsign-seal',r.id);e.dataTransfer.effectAllowed='copy';};const im=node('img');im.src=r.url;im.alt=r.name;im.draggable=false;const info=node('div','info');info.append(node('strong','',r.name),node('small','',`${r.fontSize} pt · ${t('Temporary','临时')}`));const remove=node('button','quiet','×');remove.title=t('Remove temporary item','移除临时素材');remove.onclick=e=>{e.stopPropagation();documentAssets.delete(r.id);imageCache.delete(r.id);if(chosen?.id===r.id)chosen=library[0]||null;renderLibrary();controls();};card.append(im,info,remove);card.onclick=()=>{chosen=r;renderLibrary();controls();mobile.pick();};card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chosen=r;renderLibrary();controls();}};if(r.kind==='text')card.ondblclick=()=>openText(r);box.append(card);}}

window.addEventListener('storage',async e=>{if(user?.role!=='user'||busy)return;if(e.key==='bsign-library-changed'||e.key==='bsign-space-'+user.id){try{if(e.key==='bsign-library-changed')imageCache.clear();await loadCompanies(e.key==='bsign-space-'+user.id?e.newValue:companyId);}catch(err){notice(errorMessage(err));}}});

window.addEventListener('storage',async e=>{if(e.key==='bsign-profile-changed'&&user){try{const q=await api('/me');user=q.user;csrf=q.csrf;$('account').textContent=user.name;lang=user.language||lang;translate();}catch{}}});

function syncOpacityControls(){for(const [id,item] of [['mark-opacity',selected],['seam-opacity',seam]]){const value=Math.round((item?.opacity??1)*100);$(id).disabled=!item||busy;$(id).value=value;$(id+'-value').textContent=value+'%';}}
$('mark-opacity').oninput=()=>{if(!selected||busy)return;selected.opacity=Number($('mark-opacity').value)/100;$('mark-opacity-value').textContent=$('mark-opacity').value+'%';drawMarks();};
$('seam-opacity').oninput=()=>{if(!seam||busy)return;seam.opacity=Number($('seam-opacity').value)/100;$('seam-opacity-value').textContent=$('seam-opacity').value+'%';drawSeam();};

